const products = {
  spot:{label:'Spot trading',short:'Spot',color:'#EB4646',default:20,desc:'Buy or sell the underlying asset without borrowing.'},
  futures:{label:'Futures collateral',short:'Futures',color:'#C96A6A',default:15,desc:'Margin reserved for perpetual positions; losses can reduce equity.'},
  stocks:{label:'Stocks / TradFi',short:'Stocks',color:'#A94B4B',default:10,desc:'Exposure to supported equity and traditional markets where available.'},
  lending:{label:'Lending',short:'Lending',color:'#F4F4F6',default:25,desc:'Supply assets to a lending pool; the rate can move over time.'},
  borrow:{label:'Borrowing (debt)',short:'Borrow',color:'#777C8A',default:0,desc:'Modeled debt backed by collateral; interest and liquidation risk apply.'},
  reserve:{label:'Safety reserve',short:'Reserve',color:'#4D515D',default:30,desc:'Capital kept unallocated so the plan has room to breathe.'}
};
const presets = {
  preserve:{spot:10,futures:0,stocks:5,lending:35,borrow:0,reserve:50},
  balanced:{spot:20,futures:15,stocks:10,lending:25,borrow:0,reserve:30},
  explore:{spot:25,futures:25,stocks:15,lending:20,borrow:5,reserve:10}
};
const faq = [
  ['Spot trading','Spot is the straightforward version of trading: you exchange one asset for another and own the asset you bought. There is no leverage in this bucket.'],
  ['Futures collateral','A futures position uses collateral to support a long or short contract. The position can be larger than the collateral, so the stress test treats this bucket as the highest-risk allocation.'],
  ['Lending','Lending means supplying assets to Backpack’s lending market so other participants can borrow them. You receive a variable rate; the calculator never treats it as guaranteed income.'],
  ['Borrowing','Borrowing means taking a loan against eligible collateral. The borrowed amount is debt—not extra free profit—and interest plus market moves can increase risk.'],
  ['Safety reserve','A reserve is money you intentionally leave out of active strategies. It can help absorb volatility, fees, or a margin top-up without forcing a rushed decision.'],
  ['Cross-margin & one balance','Backpack is designed around one balance across supported products. In this planner, that is represented as a composition—not a promise that every asset or market has identical collateral treatment.'],
  ['Variable income','The income range is an illustrative monthly estimate based on a conservative placeholder lending rate and modeled borrowing cost. Connect live Backpack rates before using it for a real decision.']
];
let state = {capital:1000,horizon:1,risk:'balanced',goal:'steady',lendingRate:6,borrowRate:10,allocations:{...presets.balanced},mode:'simple',radarData:null,radarSource:'demo'};
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const money = n => '$' + Math.round(Math.max(0,n)).toLocaleString('en-US');
const moneyExact = n => '$' + Math.max(0,Number(n)||0).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:2});
const pct = n => `${Math.round(n)}%`;
function renderAllocations(){
  $('#allocations').innerHTML = Object.entries(products).map(([key,p])=>`<div class="allocation-row" data-key="${key}"><div class="allocation-meta"><div class="allocation-label"><i class="swatch" style="background:${p.color}"></i>${p.label}</div><div class="allocation-values"><strong id="amount-${key}">${money(state.capital*state.allocations[key]/100)}</strong><span id="pct-${key}">${pct(state.allocations[key])}</span></div></div><div class="allocation-desc">${p.desc}</div><input class="range" data-key="${key}" type="range" min="0" max="100" step="1" value="${state.allocations[key]}" style="--fill:${state.allocations[key]}%" aria-label="${p.label} allocation" /></div>`).join('');
  $$('.range').forEach(el=>el.addEventListener('input',()=>adjustAllocation(el.dataset.key,Number(el.value))));
}
function adjustAllocation(key,value){
  const previous = state.allocations[key]; let delta = value-previous; state.allocations[key]=value;
  const order = ['reserve','lending','spot','stocks','futures','borrow'].filter(k=>k!==key);
  for(const other of order){ if(!delta) break; const available = delta>0 ? state.allocations[other] : 100-state.allocations[other]; const shift = Math.min(Math.abs(delta),available)*(delta>0?-1:1); state.allocations[other]+=shift; delta += shift; }
  state.allocations[key] -= delta;
  Object.keys(products).forEach(k=>state.allocations[k]=Math.max(0,Math.min(100,state.allocations[k])));
  renderAllocations(); recalculate();
}
function setPreset(name){state.allocations={...presets[name]}; $$('.preset').forEach(b=>b.classList.toggle('current',b.dataset.preset===name)); renderAllocations(); recalculate();}
function conicGradient(){let start=0; const chunks=[]; for(const [key,p] of Object.entries(products)){const end=start+state.allocations[key]; chunks.push(`${p.color} ${start}% ${end}%`); start=end;} return `conic-gradient(${chunks.join(',')})`;}
function recalculate(){
  const a=state.allocations,c=state.capital; const reserve=c*a.reserve/100; const lending=c*a.lending/100; const borrow=c*a.borrow/100; const active=c*(a.spot+a.futures+a.stocks)/100;
  const leverage=state.risk==='low'?1.5:state.risk==='high'?5:3; const stress=active*0.1+(c*a.futures/100)*(leverage-1)*0.1; const annualRate=Math.max(0,Number(state.lendingRate)||0)/100; const gross=lending*annualRate*(state.horizon/12); const borrowCost=borrow*(Math.max(0,Number(state.borrowRate)||0)/100)*(state.horizon/12); const upper=Math.max(0,gross-borrowCost);
  $('#donut').style.background=conicGradient(); $('#mapCapital').textContent=money(c); $('#productive').textContent=money(c-reserve); $('#reserve').textContent=money(reserve); $('#income').textContent=`${money(0)}–${money(upper)}`; $('#incomeSub').textContent=`variable carry over ${state.horizon} ${state.horizon===1?'month':'months'}`; $('#stress').textContent=`-${money(stress)} impact`;
  const riskName=state.risk[0].toUpperCase()+state.risk.slice(1); $('#riskLabel').textContent=riskName; $('#riskSub').textContent=state.risk==='low'?'larger buffer · lower exposure':state.risk==='high'?'thin buffer · amplified moves':'moderate exposure · balanced buffer'; $('#totalPct').textContent=pct(Object.values(a).reduce((x,y)=>x+y,0));
  $('#legend').innerHTML=Object.entries(products).map(([key,p])=>`<div class="legend-item"><span><i class="swatch" style="background:${p.color}"></i>${p.short}</span><strong>${pct(a[key])}</strong></div>`).join('');
  const total=Object.values(a).reduce((x,y)=>x+y,0); $('#allocationWarning').classList.toggle('hidden',Math.round(total)===100);
  let message = a.reserve<15 ? 'Your reserve is thin. A smaller active allocation can reduce the chance of a forced decision during a sharp move.' : a.lending>35 ? 'This plan leans on lending. Rates move, so treat the income range as variable and keep a reserve visible.' : a.futures>25 ? 'Futures are doing most of the heavy lifting here. Lower leverage and a wider reserve can make the plan more resilient.' : a.borrow>0 ? 'Borrowing can make capital more flexible, but debt and interest remain even when markets move against you.' : 'A visible reserve gives this composition room to breathe while you explore Backpack’s connected products.'; $('#insight p').textContent=message;
  const suggestions={steady:['Income-first starting point','Keep 40–60% in reserve, lend only the portion you can leave untouched, and keep futures small.'],growth:['Diversified growth starting point','Use a measured split across spot, stocks and lending; treat futures as a capped learning allocation, not a target return.'],learn:['Learning-first starting point','Use small spot and futures amounts, keep most capital in reserve or lending, and review the stress test before increasing exposure.']}; $('#recommendation strong').textContent=suggestions[state.goal][0]; $('#recommendation p').textContent=suggestions[state.goal][1];
  Object.entries(products).forEach(([key,p])=>{const amt=$(`#amount-${key}`), pp=$(`#pct-${key}`); if(amt)amt.textContent=money(c*a[key]/100); if(pp)pp.textContent=pct(a[key]);});
  const title=`${money(c)} · ${riskName}`; $('#cardTitle').textContent=title; $('#cardSubtitle').textContent=`${pct(a.reserve)} reserve · ${pct(a.lending)} lending · ${pct(a.spot+a.futures+a.stocks)} active`; $('#miniBars').innerHTML=Object.entries(products).map(([key,p])=>`<i class="mini-bar" title="${p.label}: ${pct(a[key])}" style="height:${Math.max(8,a[key]*.8)}px;background:${p.color}"></i>`).join(''); $('#shareId').textContent=`PLAN / ${hashCode(JSON.stringify({c,state}))}`;
}
function hashCode(str){let h=0; for(let i=0;i<str.length;i++)h=((h<<5)-h)+str.charCodeAt(i)|0; return Math.abs(h).toString(16).toUpperCase().padStart(6,'0').slice(-6);}
function encodePlan(){const payload=btoa(JSON.stringify(state)); return `${location.origin}${location.pathname}#plan=${payload}`;}
function loadPlan(){const raw=location.hash.startsWith('#plan=')?location.hash.slice(6):''; if(!raw)return; try{const parsed=JSON.parse(atob(raw)); if(parsed&&parsed.allocations){state={...state,...parsed,allocations:{...state.allocations,...parsed.allocations}}; $('#capital').value=state.capital; $('#horizon').value=state.horizon; $('#risk').value=state.risk; $('#goal').value=state.goal||'steady'; $('#lendingRate').value=state.lendingRate??6; $('#borrowRate').value=state.borrowRate??10; renderAllocations(); recalculate();}}catch(e){console.warn('Could not load plan',e)}}
