function renderModal(){const source=$('.share-preview');$('#modalCard').innerHTML=source.innerHTML;$('#xShareBtn').href=`https://x.com/intent/post?text=${encodeURIComponent('My Backpack Capital Composer plan: '+$('#cardTitle').textContent+' — '+$('#cardSubtitle').textContent)}&url=${encodeURIComponent(encodePlan())}`}
