async function connectLive(){
  const key=$('#apiKeyInput').value.trim(),secret=$('#apiSecretInput').value.trim(),status=$('#apiStatus'),button=$('#apiConnectBtn');
  if(!key||!secret){status.textContent='Enter both values from your Backpack read-only key.';return}
  button.disabled=true;status.textContent='Reading your account securely…';
  try{
    const response=await fetch('/api/backpack',{method:'POST',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({apiKey:key,apiSecret:secret})});
    const result=await response.json().catch(()=>({ok:false,error:'The connection endpoint returned an unreadable response.',code:'BAD_RESPONSE'}));
    if(!response.ok||!result.ok)throw new Error(result.error||'Connection failed');

    const data=result.data||{},positions=Array.isArray(data.positions)?data.positions:[],borrowLend=Array.isArray(data.borrowLend)?data.borrowLend:[],collateral=data.collateral&&typeof data.collateral==='object'?data.collateral:{},collateralRows=Array.isArray(collateral.collateral)?collateral.collateral:[];
    const debts=borrowLend.filter(x=>Number(x.netQuantity)<0),exposureFromPositions=positions.reduce((sum,p)=>sum+Math.abs(Number(p.netExposureNotional||0)),0),exposureFromCollateral=Math.abs(Number(collateral.netExposureFutures||0)),exposure=exposureFromPositions||exposureFromCollateral;
    const total=Number(collateral.netEquity||collateral.assetsValue||0),available=Number(collateral.netEquityAvailable||0),borrowedValue=Number(collateral.borrowLiability||collateral.liabilitiesValue||0);
    const marginFraction=Number(collateral.marginFraction),score=Number.isFinite(marginFraction)&&marginFraction>0?Math.max(35,Math.min(96,Math.round(70+marginFraction*100))):Math.max(35,Math.min(96,Math.round(82-(positions.length*3)-(debts.length*5))));
    state.radarSource='live';state.radarData={total,exposure,idle:available,borrowed:borrowedValue,score,marginFraction,activeMargin:Boolean(positions.length||exposureFromCollateral),positionCount:positions.length,debtCount:debts.length,collateralAssetCount:collateralRows.filter(row=>Number(row.totalQuantity||row.balanceNotional||0)>0).length};$('#connectionState').classList.remove('hidden');setRadarDemo();
    const warningCount=Array.isArray(result.warnings)?result.warnings.length:0;status.textContent=warningCount?`Connected. Balances loaded; ${warningCount} optional detail${warningCount===1?' is':'s are'} unavailable for this account.`:'Connected. Credentials discarded from this browser.';closeConnect();toast(warningCount?'Backpack connected with partial details':'Backpack account connected');
  }catch(error){status.textContent=error.message||'Connection failed. Check the key and Read Only permission.';toast('Could not connect')}
  finally{button.disabled=false;$('#apiKeyInput').value='';$('#apiSecretInput').value=''}
}
$('#apiConnectBtn').addEventListener('click',connectLive);
document.addEventListener('click',e=>{if(e.target.closest('#tipBtn'))openTip();if(e.target.closest('#manualBtn'))openManual();if(e.target.closest('#copyTipBtn')){navigator.clipboard?.writeText($('#tipAddress').textContent.trim()).then(()=>toast('Solana address copied')).catch(()=>toast('Select the address to copy'))}});
function readManualValue(id){return Math.max(0,Number($(`#${id}`).value)||0)}
function validateManualSnapshot(){const total=readManualValue('manualTotal'),entered=readManualValue('manualSpot')+readManualValue('manualFutures')+readManualValue('manualStocks')+readManualValue('manualLending')+readManualValue('manualReserve'),note=$('#manualValidation'),button=$('#manualApplyBtn');if(!note||!button)return true;if(entered>total&&total>=0){note.textContent=`Entered balances total ${moneyExact(entered)}, which is above the ${moneyExact(total)} account value. Clear or reduce a bucket before generating the radar.`;note.classList.remove('hidden');button.disabled=true;return false}note.textContent='';note.classList.add('hidden');button.disabled=false;return true}
function openManual(){ $('#manualModal').classList.add('open');$('#manualModal').setAttribute('aria-hidden','false');validateManualSnapshot() } function closeManual(){ $('#manualModal').classList.remove('open');$('#manualModal').setAttribute('aria-hidden','true') }
function applyManualSnapshot(){if(!validateManualSnapshot())return;const total=readManualValue('manualTotal'),spot=readManualValue('manualSpot'),futures=readManualValue('manualFutures'),stocks=readManualValue('manualStocks'),lending=readManualValue('manualLending'),reserve=readManualValue('manualReserve'),borrowed=readManualValue('manualBorrowed'),active=spot+futures+stocks;state.radarSource='manual';state.radarData={total,exposure:active,idle:lending+reserve,borrowed,reserve,lending,spot,futures,stocks,productShares:{spot:total?spot/total*100:0,futures:total?futures/total*100:0,stocks:total?stocks/total*100:0,lending:total?lending/total*100:0,reserve:total?reserve/total*100:0}};closeManual();$('#connectionState').classList.remove('hidden');$('#connectionLabel').textContent='Manual snapshot · nothing shared';setRadarDemo();toast('Manual Radar generated')}
$('#manualBtn').addEventListener('click',openManual);$$('[data-close-manual]').forEach(el=>el.addEventListener('click',closeManual));$('#manualApplyBtn').addEventListener('click',applyManualSnapshot);
$$('.manual-fields input').forEach(input=>input.addEventListener('input',validateManualSnapshot));
function openTip(){ $('#tipModal').classList.add('open');$('#tipModal').setAttribute('aria-hidden','false') } function closeTip(){ $('#tipModal').classList.remove('open');$('#tipModal').setAttribute('aria-hidden','true') }
$('#tipBtn').addEventListener('click',openTip);$$('[data-close-tip]').forEach(el=>el.addEventListener('click',closeTip));$('#copyTipBtn').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#tipAddress').textContent.trim());toast('Solana address copied')}catch(e){toast('Copy failed — select the address')}});
